INSERT INTO `contract_templates` (`id`, `tenant_id`, `name`, `content`, `has_border`, `is_default`, `updated_at`) VALUES
	(1, 1, 'Hizmet Sözleşmesi Şablonu', '<h2 class="ql-align-center"><strong class="ql-font-times"> HİZMET SÖZLEŞMESİ</strong></h2><p class="ql-align-center"><span class="ql-font-times">(657 sayılı Devlet Memurları Kanununun 4/B maddesi uyarınca çalıştırılacak sözleşmeli personel için)</span></p><h3 class="ql-align-justify"><br></h3><p class="ql-align-justify"><span class="ql-font-times">{{KURUM_ADI}} adına hareket eden Rektör </span><strong class="ql-font-times">{{YETKILI_AD}}</strong><span class="ql-font-times"> ile {{GOREV}} görevinde istihdam edilecek </span><strong class="ql-font-times">{{PERSONEL_AD}}</strong><span class="ql-font-times"> arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır.</span></p><p class="ql-align-justify"><span class="ql-font-times">Sözleşmede geçen “Kurum” deyimi, </span><strong class="ql-font-times">{{KURUM_ADI}}</strong><span class="ql-font-times">’ni, “ilgili” deyimi </span><strong class="ql-font-times">{{PERSONEL_AD}}</strong><span class="ql-font-times"> isimli sözleşmeli personeli tanımlamaktadır.</span></p><p class="ql-align-justify"><strong class="ql-font-times"> </strong>	<strong class="ql-font-times">Madde 1-</strong><span class="ql-font-times"> İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 2-</strong><span class="ql-font-times"> İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 3-</strong><span class="ql-font-times"> İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, haftanın belli gün ve saatlerinde kısmi zamanlı olarak çalışanların çalışma saat ve süreleri, devlet memurları için saptanan çalışma saat ve süreleri esas alınarak Kurumca belirlenir.</span></p><p class="ql-align-justify"><span class="ql-font-times">Ayrıca, ilgili kendisine verilen işleri bitirene kadar, normal çalışma saatleri dışında da çalışmak zorundadır. Normal çalışma saatleri dışında veya tatil günlerinde yapacağı çalışmalar karşılığında ilgiliye herhangi bir ek ücret ödenmez.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 4-</strong><span class="ql-font-times"> İlgiliye, yapacağı hizmete karşılık sözleşme süresince her ay brüt (</span><strong class="ql-font-times">{{EGITIM_DURUMU}}</strong><span class="ql-font-times">) </span><strong class="ql-font-times">{{BRUT_UCRET}}</strong><span class="ql-font-times"> ücret ödenir. Ödemeler her aybaşında peşin olarak yapılır. Devlet Memuru aylıklarında genel bir artış yapılması durumunda, bu sözleşme ücreti yeni bir karar alınmasına gerek bulunmaksızın aynı oran ve/veya miktarda artırılır.</span></p><p class="ql-align-justify"><span class="ql-font-times">Ay sonundan önce ayrılmalarda, 5510 sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu hükümlerine göre aylık bağlanması veya ölüm sebebiyle sözleşmeye son verilmesi halleri dışında, kalan günlere düşen ücret tutarı ilgiliden doğrudan geri alınır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 5-</strong><span class="ql-font-times"> Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların 4.maddesinde yer alan hükümler kapsamında ilgili, görev yeri dışında geçici olarak görevlendirildiğinde gündelik ve yol giderleri, her yıl bütçe kanunları ile 6245 Sayılı Harcırah Kanununun 33. Maddesine göre belirlenen aylık kadro derecesi 5-15 olanlar için tespit edilen esaslara göre hesaplanır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 6-</strong><span class="ql-font-times"> İlgili, dışarıda kazanç getirici başka bir iş yapamaz. (Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların 8 nci maddesinde sayılanlar hariç)</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 7-</strong><span class="ql-font-times"> 217 Sayılı Kanun Hükmünde Kararnamenin 2 nci maddesinde belirtilen kurumlarda geçen hizmet süresi, bir yıldan on yıla kadar olan personele yirmi gün, on yıldan fazla olanlara otuz gün ücretli yıllık izin verilir. Rapor sebebiyle, Sosyal Sigortalar Kurumunca ödenen geçici iş göremezlik tazminatı ilginin ücretinden düşülür.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 8-</strong><span class="ql-font-times"> İlgili kanunlar uyarınca resmi kıyafet giymek zorunda bulunan personel için 14/9/1991 tarihli ve 91/2268 sayılı Bakanlar Kurulu kararı ile yürürlüğe konulan Memurlara Giyecek Yardımı Yönetmeliği\'nde öngörülmüş olan giyim eşyalarından emsali sözlemeli personel de aynı esas ve usüller çerçevesinde faydalandırılır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 9 -</strong><span class="ql-font-times">a) İlgilinin sözleşmesi Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların ek 6.maddesinde belirtilen hallerden herhangi birinin gerçekleşmesi halinde sona erer.Bu durum kurumca ilgiliye yazılı olarak tebliğ edilir. Tebliğatta belirtilecek günden geçerli olmak üzere sözleşme sona erer.</span></p><p class="ql-align-justify"><span class="ql-font-times">b) İlgilinin 65 yaşını doldurduğu tarihte hiçbir işleme gerek kalmaksızın sözleşmesi sona erer.</span></p><p class="ql-align-justify"><span class="ql-font-times">c) Taraflar bir ay önce ihbar etmek şartıyla sebeb göstermeksizin sözleşmeyi feshedebilir.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 10-</strong><span class="ql-font-times"> İlgilinin disiplin işlemlerinde; 657 Sayılı Devlet Memurları kanununda yer alan disiplin hükümleri uygulanır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 11-</strong><span class="ql-font-times"> Sözleşme düzenlenmesinin gerektirdiği her türlü giderler Kurumca karşılanır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 12-</strong><span class="ql-font-times"> Bu sözleşmeden doğacak uyuşmazlık Düzce Mahkemelerince çözümlenir.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 13-</strong><span class="ql-font-times"> İş bu sözleşme .../.../2026 tarihinden </span><strong class="ql-font-times">{{BITIS_TARIHI}}</strong><span class="ql-font-times"> tarihine kadar geçerlidir.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 14-</strong><span class="ql-font-times"> Bu sözleşme, 657 Sayılı Kanunun 4/B maddesi ve Sözleşmeli Personel Çalıştırılmasına İlişkin Esaslar uyarınca akdedilmiştir. İlgilinin kullanabileceği izinler, ilgiliye ödenecek İş Sonu Tazminatı ve bu sözleşmede yer almayan diğer hususlar hakkında anılan Esaslara ilişkin hükümler ve aykırı olmamak kaydıyla diğer kanun hükümleri çerçevesinde işlem yapılır.</span></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><table class="no-borders" style="margin-left: auto; margin-right: auto; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important;" data-no-borders="true"><tbody><tr height="18px" style="height: 18px !important;" data-row-height="18px"><td data-row="1" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><span style="font-size: 13px;">Sözleşmeli Personel</span></td><td data-row="1" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><br></td><td data-row="1" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><span style="font-size: 13px;">Kurum Yetkilisi</span></td></tr><tr height="18px" style="height: 18px !important;" data-row-height="18px"><td data-row="2" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important; cursor: col-resize;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><strong style="color: rgb(67, 56, 202); font-size: 13px;">{{PERSONEL_AD}}</strong></td><td data-row="2" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important; cursor: col-resize;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><br></td><td data-row="2" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><strong style="color: rgb(67, 56, 202); font-size: 13px;">{{YETKILI_AD}}</strong></td></tr><tr height="18px" style="height: 18px !important;" data-row-height="18px"><td data-row="3" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><strong style="color: rgb(67, 56, 202); font-size: 13px;">{{GOREV}}</strong></td><td data-row="3" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><br></td><td data-row="3" class="ql-align-center" style="width: 120px !important; min-width: 120px !important; max-width: 120px !important; border-width: medium !important; border-style: none !important; border-color: currentcolor !important; border-image: initial !important; height: 18px !important; line-height: 18px !important; font-size: 18px !important; vertical-align: top !important; padding-top: 0px !important; padding-bottom: 0px !important;" data-col-width="120px" width="120px" height="18px" data-row-height="18px" data-no-borders="true"><strong style="color: rgb(67, 56, 202); font-size: 13px;">{{YETKILI_UNVAN}}</strong></td></tr></tbody></table>', 1, 0, '2026-05-18 09:36:23'),
	(2, 2, 'Hizmet Sözleşmesi Şablonu', '<h2 class="ql-align-center"><span class="ql-font-times">HİZMET SÖZLEŞMESİ</span></h2><p class="ql-align-center"><strong class="ql-font-times">(657 sayılı Devlet Memurları Kanununun 4 üncü maddesinin (B) fıkrası uyarınca çalıştırılacak sözleşmeli personel için)</strong></p><p><br></p><p><span class="ql-font-times">{{KURUM_ADI}} adına hareket eden {{YETKILI_AD}} ile {{GOREV}} görevinde istihdam edilecek {{PERSONEL_AD}} arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır.</span></p><p><span class="ql-font-times">Sözleşmede geçen "Kurum" deyimi, {{KURUM_ADI}}, "İlgili" deyimi {{PERSONEL_AD}} isimli sözleşmeli personeli tanımlamaktadır.</span></p><p><strong class="ql-font-times">Madde 1</strong><span class="ql-font-times">- İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder.</span></p><p><strong class="ql-font-times">Madde 2</strong><span class="ql-font-times">- İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır.</span></p><p><strong class="ql-font-times">Madde 3</strong><span class="ql-font-times">- İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, ilgili o gün bitirilmesi gereken işlerin bitimine kadar çalışmak zorundadır.</span></p><p><strong class="ql-font-times">Madde 4</strong><span class="ql-font-times">- İlgiliye, yapacağı hizmete karşılık sözleşme süresince her ay brüt ({{BRUT_UCRET}}) TL ücret ödenir. Ödemeler her aybaşında peşin olarak yapılır.</span></p><p><strong class="ql-font-times">Madde 10</strong><span class="ql-font-times">- İşbu sözleşme {{BASLANGIC_TARIHI}} tarihinden {{BITIS_TARIHI}} tarihine kadar geçerlidir.</span></p><p><br></p><p><br></p><p><strong class="ql-font-times">Sözleşmeli Personel</strong></p><p><br></p><p><br></p><p> _________________ <strong>Kurum Yetkilisi</strong></p><p><br></p><p><br></p><p> _________________ </p>', 0, 0, '2026-04-26 16:03:56'),
	(3, 3, 'Hizmet Sözleşmesi Şablonu', '<h2 class="ql-align-center"><span class="ql-font-times">HİZMET SÖZLEŞMESİ</span></h2><p class="ql-align-center"><strong class="ql-font-times">(657 sayılı Devlet Memurları Kanununun 4 üncü maddesinin (B) fıkrası uyarınca çalıştırılacak sözleşmeli personel için)</strong></p><p><br></p><p><span class="ql-font-times">{{KURUM_ADI}} adına hareket eden {{YETKILI_AD}} ile {{GOREV}} görevinde istihdam edilecek {{PERSONEL_AD}} arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır.</span></p><p><span class="ql-font-times">Sözleşmede geçen "Kurum" deyimi, {{KURUM_ADI}}, "İlgili" deyimi {{PERSONEL_AD}} isimli sözleşmeli personeli tanımlamaktadır.</span></p><p><strong class="ql-font-times">Madde 1</strong><span class="ql-font-times">- İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder.</span></p><p><strong class="ql-font-times">Madde 2</strong><span class="ql-font-times">- İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır.</span></p><p><strong class="ql-font-times">Madde 3</strong><span class="ql-font-times">- İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, ilgili o gün bitirilmesi gereken işlerin bitimine kadar çalışmak zorundadır.</span></p><p><strong class="ql-font-times">Madde 4</strong><span class="ql-font-times">- İlgiliye, yapacağı hizmete karşılık sözleşme süresince her ay brüt ({{BRUT_UCRET}}) TL ücret ödenir. Ödemeler her aybaşında peşin olarak yapılır.</span></p><p><strong class="ql-font-times">Madde 10</strong><span class="ql-font-times">- İşbu sözleşme {{BASLANGIC_TARIHI}} tarihinden {{BITIS_TARIHI}} tarihine kadar geçerlidir.</span></p><p><br></p><p><br></p><p><strong class="ql-font-times">Sözleşmeli Personel</strong><span class="ql-font-times">											 															</span><strong class="ql-font-times">Kurum Yetkilisi</strong></p><p><br></p><p><br></p><p><span class="ql-font-times"> _________________ </span></p>', 0, 0, '2026-04-26 16:48:02'),
	(4, 5, 'Hizmet Sözleşmesi Şablonu', '<h1 class="ql-align-center"><span style="font-size: 13px;">HİZMET SÖZLEŞMESİ</span></h1><p class="ql-align-center"><span style="font-size: 13px;">(657 sayılı Devlet Memurları Kanununun 4/B maddesi uyarınca çalıştırılacak sözleşmeli personel için)</span></p><p><span style="font-size: 11px;">{{KURUM_ADI}} adına hareket eden Rektör </span><strong style="font-size: 11px;">{{YETKILI_AD}}</strong><span style="font-size: 11px;"> ile {{GOREV}} görevinde istihdam edilecek </span><strong style="font-size: 11px;">{{PERSONEL_AD}}</strong><span style="font-size: 11px;"> arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır.</span></p><p><span style="font-size: 11px;">Sözleşmede geçen “Kurum” deyimi, </span><strong style="font-size: 11px;">{{KURUM_ADI}}</strong><span style="font-size: 11px;">’ni, “ilgili” deyimi </span><strong style="font-size: 11px;">{{PERSONEL_AD}}</strong><span style="font-size: 11px;"> isimli sözleşmeli personeli tanımlamaktadır.</span></p><p><strong style="font-size: 11px;">Madde 1-</strong><span style="font-size: 11px;"> İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder.</span></p><p><strong style="font-size: 11px;">Madde 2-</strong><span style="font-size: 11px;"> İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır.</span></p><p><strong style="font-size: 11px;">Madde 3-</strong><span style="font-size: 11px;"> İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, haftanın belli gün ve saatlerinde kısmi zamanlı olarak çalışanların çalışma saat ve süreleri, devlet memurları için saptanan çalışma saat ve süreleri esas alınarak Kurumca belirlenir.</span></p><p><span style="font-size: 11px;">Ayrıca, ilgili kendisine verilen işleri bitirene kadar, normal çalışma saatleri dışında da çalışmak zorundadır. Normal çalışma saatleri dışında veya tatil günlerinde yapacağı çalışmalar karşılığında ilgiliye herhangi bir ek ücret ödenmez.</span></p><p><strong style="font-size: 11px;">Madde 4-</strong><span style="font-size: 11px;"> İlgiliye, yapacağı hizmete karşılık sözleşme süresince her ay brüt (</span><strong style="font-size: 11px;">{{EGITIM_DURUMU}}</strong><span style="font-size: 11px;">) </span><strong style="font-size: 11px;">{{BRUT_UCRET}} TL</strong><span style="font-size: 11px;"> ücret ödenir. Ödemeler her aybaşında peşin olarak yapılır. Devlet Memuru aylıklarında genel bir artış yapılması durumunda, bu sözleşme ücreti yeni bir karar alınmasına gerek bulunmaksızın aynı oran ve/veya miktarda artırılır.</span></p><p><span style="font-size: 11px;">Ay sonundan önce ayrılmalarda, 5510 sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu hükümlerine göre aylık bağlanması veya ölüm sebebiyle sözleşmeye son verilmesi halleri dışında, kalan günlere düşen ücret tutarı ilgiliden doğrudan geri alınır.</span></p><p><strong style="font-size: 11px;">Madde 5-</strong><span style="font-size: 11px;"> Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların 4.maddesinde yer alan hükümler kapsamında ilgili, görev yeri dışında geçici olarak görevlendirildiğinde gündelik ve yol giderleri, her yıl bütçe kanunları ile 6245 Sayılı Harcırah Kanununun 33. Maddesine göre belirlenen aylık kadro derecesi 5-15 olanlar için tespit edilen esaslara göre hesaplanır.</span></p><p><strong style="font-size: 11px;">Madde 6-</strong><span style="font-size: 11px;"> İlgili, dışarıda kazanç getirici başka bir iş yapamaz. (Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların 8 nci maddesinde sayılanlar hariç)</span></p><p><strong style="font-size: 11px;">Madde 7-</strong><span style="font-size: 11px;"> 217 Sayılı Kanun Hükmünde Kararnamenin 2 nci maddesinde belirtilen kurumlarda geçen hizmet süresi, bir yıldan on yıla kadar olan personele yirmi gün, on yıldan fazla olanlara otuz gün ücretli yıllık izin verilir. Rapor sebebiyle, Sosyal Sigortalar Kurumunca ödenen geçici iş göremezlik tazminatı ilginin ücretinden düşülür.</span></p><p><strong style="font-size: 11px;">Madde 8-</strong><span style="font-size: 11px;"> İlgili kanunlar uyarınca resmi kıyafet giymek zorunda bulunan personel için 14/9/1991 tarihli ve 91/2268 sayılı Bakanlar Kurulu kararı ile yürürlüğe konulan Memurlara Giyecek Yardımı Yönetmeliği\'nde öngörülmüş olan giyim eşyalarından emsali sözlemeli personel de aynı esas ve usüller çerçevesinde faydalandırılır.</span></p><p><strong style="font-size: 11px;">Madde 9 -</strong><span style="font-size: 11px;">a) İlgilinin sözleşmesi Sözleşmeli Personel Çalıştırılmasına İlişkin Esasların ek 6.maddesinde belirtilen hallerden herhangi birinin gerçekleşmesi halinde sona erer.Bu durum kurumca ilgiliye yazılı olarak tebliğ edilir. Tebliğatta belirtilecek günden geçerli olmak üzere sözleşme sona erer.</span></p><p><span style="font-size: 11px;">b) İlgilinin 65 yaşını doldurduğu tarihte hiçbir işleme gerek kalmaksızın sözleşmesi sona erer.</span></p><p><span style="font-size: 11px;">c) Taraflar bir ay önce ihbar etmek şartıyla sebeb göstermeksizin sözleşmeyi feshedebilir.</span></p><p><strong style="font-size: 11px;">Madde 10-</strong><span style="font-size: 11px;"> İlgilinin disiplin işlemlerinde; 657 Sayılı Devlet Memurları kanununda yer alan disiplin hükümleri uygulanır.</span></p><p><strong style="font-size: 11px;">Madde 11-</strong><span style="font-size: 11px;"> Sözleşme düzenlenmesinin gerektirdiği her türlü giderler Kurumca karşılanır.</span></p><p><strong style="font-size: 11px;">Madde 12-</strong><span style="font-size: 11px;"> Bu sözleşmeden doğacak uyuşmazlık Düzce Mahkemelerince çözümlenir.</span></p><p><strong style="font-size: 11px;">Madde 13-</strong><span style="font-size: 11px;"> İş bu sözleşme </span><strong style="font-size: 11px;">{{BASLANGIC_TARIHI}}</strong><span style="font-size: 11px;"> tarihinden </span><strong style="font-size: 11px;">{{BITIS_TARIHI}}</strong><span style="font-size: 11px;"> tarihine kadar geçerlidir.</span></p><p><strong style="font-size: 11px;">Madde 14-</strong><span style="font-size: 11px;"> Bu sözleşme, 657 Sayılı Kanunun 4/B maddesi ve Sözleşmeli Personel Çalıştırılmasına İlişkin Esaslar uyarınca akdedilmiştir. İlgilinin kullanabileceği izinler, ilgiliye ödenecek İş Sonu Tazminatı ve bu sözleşmede yer almayan diğer hususlar hakkında anılan Esaslara ilişkin hükümler ve aykırı olmamak kaydıyla diğer kanun hükümleri çerçevesinde işlem yapılır.</span></p><p><br></p><p><strong style="font-size: 13px;">Sözleşmeli Personel</strong></p><p><span style="font-size: 13px;">{{PERSONEL_AD}}</span></p><p><span style="font-size: 13px;">{{GOREV}}</span></p><p><strong style="font-size: 13px;">Kurum Yetkilisi</strong></p><p><strong style="font-size: 13px;">{{YETKILI_AD}}</strong></p><p><span style="font-size: 13px;">{{YETKILI_UNVAN}}</span></p>', 1, 0, '2026-05-01 12:26:04'),
	(5, 6, 'Hizmet Sözleşmesi Şablonu', '<h1 class="ql-align-center"><strong class="ql-font-times"> HİZMET SÖZLEŞMESİ</strong></h1><p class="ql-align-center"><span class="ql-font-times">(657 sayılı Devlet Memurları Kanununun 4/B maddesi uyarınca çalıştırılacak sözleşmeli personel için)</span></p><h3 class="ql-align-justify"><br></h3><p class="ql-align-justify"><span class="ql-font-times">{{KURUM_ADI}} adına hareket eden Rektör </span><strong class="ql-font-times">{{YETKILI_AD}}</strong><span class="ql-font-times"> ile {{GOREV}} görevinde istihdam edilecek </span><strong class="ql-font-times">{{PERSONEL_AD}}</strong><span class="ql-font-times"> arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır.</span></p><p class="ql-align-justify"><span class="ql-font-times">Sözleşmede geçen “Kurum” deyimi, </span><strong class="ql-font-times">{{KURUM_ADI}}</strong><span class="ql-font-times">’ni, “ilgili” deyimi </span><strong class="ql-font-times">{{PERSONEL_AD}}</strong><span class="ql-font-times"> isimli sözleşmeli personeli tanımlamaktadır.</span></p><p class="ql-align-justify"><strong class="ql-font-times"> </strong>	<strong class="ql-font-times">Madde 1-</strong><span class="ql-font-times"> İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 2-</strong><span class="ql-font-times"> İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır.</span></p><p class="ql-align-justify">&nbsp;&nbsp;&nbsp;&nbsp;<strong class="ql-font-times">Madde 3-</strong><span class="ql-font-times"> İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, haftanın belli gün ve saatlerin