INSERT INTO `rich_texts` (`id`, `record_type`, `record_id`, `field`, `body`, `created_at`, `updated_at`) VALUES
	(1, 'App\\Models\\ContractDraft', 1, 'content', '\n', '2026-04-21 09:58:32', '2026-04-21 09:58:32'),
	(2, 'App\\Models\\Setting', 1, 'contract_template', '<p style="text-align: center;"><br></p><p style="text-align: center;"><strong>HİZMET SÖZLEŞMESİ</strong> </p><p style="text-align: center;">(657 sayılı Devlet Memurları Kanununun 4 üncü maddesinin (B) fıkrası uyarınca çalıştırılacak sözleşmeli personel için) </p><p><br></p><p> <strong>{{ kurum_adi }}</strong> adına hareket eden <strong>{{ kurum_yetkilisi }}</strong> ile <strong>{{ personel_unvani }}</strong> görevinde istihdam edilecek <strong>{{ personel_ad_soyad }}</strong> arasında aşağıdaki şartlarda bu hizmet sözleşmesi yapılmıştır. Sözleşmede geçen “Kurum” deyimi, <strong>{{ kurum_adi }}</strong> , “ilgili” deyimi <strong>{{ personel_ad_soyad }}</strong> isimli sözleşmeli personeli tanımlamaktadır. Madde 1- İlgili, Kurumca gösterilecek görev yerlerinde mevzuat ve verilecek emirler çerçevesinde göreviyle ilgili kendisine verilen tüm işleri yapmayı taahhüt eder. Madde 2- İlgili, görevi sırasında edindiği gizli bilgileri, görevinden ayrılsa bile Kurumun izni olmadan açıklayamaz. İlgili, görevi sona erdiği zaman elinde bulunan Kuruma ait araç, gereç ve belgeleri geri vermek zorundadır. Madde 3- İlgilinin çalışma saat ve süreleri, Devlet memurları için saptanan çalışma saat ve sürelerinin aynıdır. Ancak, ilgili o gün bitirilmesi gereken işlerin bitimine kadar çalışmak zorundadır. Normal çalışma sürelerini aşan bu süreler için ilgili kanunlarında öngörülen hükümler saklı kalmak kaydıyla her sekiz saati için bir gün hesabıyla izin verilir. Madde 4- İlgiliye, yapacağı hizmete karşılık sözleşme süresince her ay brüt (<strong>{{ personel_ucret }}</strong>) TL ücret ödenir. Ödemeler her aybaşında peşin olarak yapılır. Ay sonundan önce ayrılmalarda, 5510 sayılı Sosyal Sigortalar ve Genel Sağlık Sigortası Kanunu hükümlerine göre aylık bağlanması veya ölüm sebebiyle sözleşmeye son verilmesi halleri dışında, kalan günlere düşen ödemeler ilgiliden doğrudan geri alınır. Madde 5- 6/6/1978 tarihli ve 7/15754 sayılı Kararnamenin 4 üncü maddesinde yer alan hükümler kapsamında İlgili, görev yeri dışında görevlendirildiğinde gündelik ve yol giderleri, ......... derece Devlet memurları için 6245 sayılı Harcırah Kanunu ile tespit edilen esaslara göre hesaplanır. Madde 6- İlgili, dışarıda kazanç getirici başka bir iş yapamaz.( 7/15754 sayılı Kararnamenin 8 nci maddesinde sayılanlar hariç) Madde 7- a) İlgilinin sözleşmesi 7/15754 sayılı Kararnamenin ek 6 ncı maddesinde belirtilen hallerden herhangi birinin gerçekleşmesi halinde sona erer. Bu durum Kurumca ilgiliye yazılı olarak tebliğ edilir. Tebligatta belirtilecek günden geçerli olmak üzere sözleşme sona erer. b) İlgilinin, 65 yaşını doldurduğu tarihte hiçbir işleme gerek kalmaksızın sözleşmesi sona erer. Madde 8- Sözleşme düzenlenmesinin gerektirdiği her türlü giderler Kurumca karşılanır. Madde 9- Bu sözleşmeden doğacak uyuşmazlık ........................... Mahkemelerince çözümlenir. Madde 10- İşbu sözleşme .................. tarihinden ................. tarihine kadar geçerlidir. Madde 11- Bu sözleşme, 657 sayılı Kanunun 4 üncü maddesinin (B) fıkrası ve 7/15754 sayılı Kararname uyarınca akdedilmiştir. İlgilinin kullanabileceği izinler, ilgiliye ödenebilecek iş sonu tazminatı ve bu sözleşmede yer almayan diğer hususlar hakkında anılan Kararname hükümleri çerçevesinde işlem yapılır. </p><p>Sözleşmeli Personel 																																																																														Kurum Yetkilisi\n</p>', '2026-04-23 07:24:27', '2026-04-23 08:02:18');
